+import { formatMoney } from './format.js';
+
+// RFC 4180: quote a field that holds a comma, a quote or a newline.
+const field = (s) => (/[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s);
+
+// Invoice lines as CSV, for pasting into a spreadsheet.
+export function toCsv(lines) {
+  const rows = lines.map((l) =>
+    [field(l.description), l.qty, formatMoney(l.cents), formatMoney(l.cents * l.qty)].join(','));
+  return ['description,qty,unit,total', ...rows].join('\n');
+}
